const DATA={"configs":{"norberg-2004-hydrolysis-op-1":{"title":"Metal acetate solution","art":"charge","names":["Zn(OAc)₂·2H₂O","Mn(OAc)₂·4H₂O"],"specimen":"DMSO solution","extra_rows":[{"label":"Temperature","value":"Room temperature"}],"note":"Prepare a DMSO solution containing a total of 0.10 M manganese and zinc acetates at the selected Mn:Zn feed ratio, at room temperature under atmospheric conditions. Absolute reagent charges, solution volumes and the feed ratio for every characterized specimen are not reported."},"norberg-2004-hydrolysis-op-2":{"title":"Dropwise base addition","art":"drop","names":["TMAH in ethanol"],"specimen":"Metal acetate solution","extra_rows":[{"label":"Temperature","value":"Room temperature"},{"label":"Addition","value":"Dropwise, constant stirring"}],"note":"Add 1.7 equivalents of 0.55 M ethanolic tetramethylammonium hydroxide dropwise under constant stirring at room temperature. The source identifies the pentahydrate. Addition duration, drop rate and stirring speed are not reported."},"norberg-2004-hydrolysis-op-3":{"title":"Nanocrystal growth and ripening","art":"ripen","names":[],"specimen":"Growing colloids","extra_rows":[{"label":"Initial growth","value":"Minutes"},{"label":"Later alternatives","value":"Several days at room temperature OR near 60 °C"}],"note":"Allow initial nanocrystal growth over minutes. Further ripening may proceed for several days at room temperature or be accelerated near 60 °C. These are alternatives; the common route does not specify a single numerical growth endpoint."},"norberg-2004-hydrolysis-op-4":{"title":"Ethyl acetate precipitation","art":"precipitate","names":["Ethyl acetate"],"specimen":"Grown nanocrystals","extra_rows":[{"label":"Retain","value":"Nanocrystal fraction"},{"label":"Separation equipment","value":"Not reported"}],"note":"After growth, precipitate the nanocrystals with ethyl acetate and retain the particle fraction. Antisolvent volume and the separation equipment, force and duration are not reported."},"norberg-2004-hydrolysis-op-5":{"title":"Ethanol resuspension","art":"redisperse","names":["Ethanol"],"specimen":"Recovered nanocrystals","extra_rows":[{"label":"Solvent amount","value":"Not reported"}],"note":"Resuspend the recovered nanocrystals in ethanol. The ethanol amount is not reported."},"norberg-2004-hydrolysis-op-6":{"title":"Repeated precipitation and washing","art":"wash","names":["Heptane","Ethanol"],"specimen":"Nanocrystal fraction","extra_rows":[{"label":"Sequence","value":"Heptane precipitation / ethanol resuspension"},{"label":"Cycle count","value":"Not reported"}],"note":"Wash by repeated heptane precipitation and ethanol resuspension, retaining the nanocrystal fraction. Solvent volumes, cycle count and separation settings are not specified."},"norberg-2004-hydrolysis-op-7":{"title":"Initial dodecylamine capping","art":"cap","names":["Dodecylamine","Toluene"],"specimen":"Washed nanocrystals","extra_rows":[{"label":"Treatment","value":"Initial capping, distinct from later cleaning"}],"note":"Cap the washed nanocrystals with dodecylamine and transfer them into toluene. The initial capping amount, temperature and duration are unreported. This stage is distinct from the subsequent 180 °C surface-cleaning treatment."},"norberg-2004-amine-cleaning-op-1":{"title":"Thermal surface cleaning","art":"heat","names":["Dodecylamine"],"specimen":"Capped colloids","extra_rows":[{"label":"Heating ramp","value":"Not reported"}],"note":"Heat the dodecylamine-capped colloids in dodecylamine at 180 °C for approximately 30 min under nitrogen. Nanocrystal and amine charges and the heating ramp are not reported. Dodecylamine's approximately 30 °C melting point is a separate reagent property, not an additional synthesis hold."},"norberg-2004-amine-cleaning-op-2":{"title":"Cooling before precipitation","art":"cool","names":[],"specimen":"Treated colloids","extra_rows":[{"label":"Cooling rate","value":"Not reported"}],"note":"Cool the treated material strictly below 80 °C before precipitation. The cooling rate is not reported."},"norberg-2004-amine-cleaning-op-3":{"title":"Ethanol precipitation and washing","art":"wash","names":["Ethanol"],"specimen":"Treated nanocrystals","extra_rows":[{"label":"Retain","value":"Nanocrystal fraction"},{"label":"Volumes / cycles","value":"Not reported"}],"note":"Precipitate and wash the treated nanocrystals with ethanol, retaining the particle fraction. Ethanol volumes, washing repetitions and separation settings are not specified."},"norberg-2004-amine-cleaning-op-4":{"title":"Nonpolar redispersion","art":"redisperse","names":["Toluene / nonpolar solvent"],"specimen":"Cleaned nanocrystals","extra_rows":[{"label":"Storage","value":"Several months reported; quantitative conditions absent"}],"note":"Redisperse the cleaned nanocrystals in toluene or another nonpolar solvent. The authors report optically high-quality dispersions stable for several months; storage temperature, atmosphere and illumination are unspecified."},"norberg-2004-surface-control-op-1":{"title":"Prepare pure-ZnO reference","art":"control-particles","names":["Ethanol"],"specimen":"Pure ZnO control","extra_rows":[{"label":"Upstream","value":"Common route without manganese feed"}],"note":"Prepare pure ZnO through the common route without manganese feed, then wash and resuspend the particles in ethanol. This upstream preparation produces the substrate for the deliberately surface-bound Mn reference."},"norberg-2004-surface-control-op-2":{"title":"Add surface-reference manganese","art":"particle-add","names":["Mn(OAc)₂·4H₂O"],"specimen":"Pure ZnO dispersion","extra_rows":[{"label":"Charge meaning","value":"Added Mn relative to Zn, not measured internal doping"}],"note":"Add a small manganese acetate charge, approximately 2% relative to Zn²⁺, to the pure-ZnO dispersion. This percentage describes the added charge, not an ICP-measured internal dopant fraction. Absolute charge and contact time are unreported."},"norberg-2004-surface-control-op-3":{"title":"Add ethanolic LiOH dropwise","art":"particle-drop","names":["LiOH in ethanol"],"specimen":"Surface-control mixture","extra_rows":[{"label":"Addition","value":"Dropwise"},{"label":"Concentration / volume","value":"Not reported"}],"note":"Add 0.002 equivalent of ethanolic LiOH to the surface-control preparation. The source does not explicitly state the equivalent reference, LiOH concentration or added volume."},"norberg-2004-surface-control-op-4":{"title":"Surface-reference washing and capping","art":"cap","names":["Dodecylamine","Toluene"],"specimen":"Surface-Mn reference","extra_rows":[{"label":"Subsequent analysis","value":"EPR"},{"label":"Thermal stripping","value":"180 °C treatment is not applied"}],"note":"Wash the surface-control particles, cap them with dodecylamine and resuspend them in toluene for EPR. This deliberately surface-bound reference does not receive the later 180 °C surface-stripping treatment. Detailed washing and capping conditions are unreported."},"norberg-2004-topo-op-1":{"title":"TOPO surface treatment","art":"heat","names":["Technical TOPO"],"specimen":"Nanocrystals","extra_rows":[{"label":"Method","value":"Heating, referred to reference 32"},{"label":"Specimen","value":"1.1% Mn optical / MCD context"}],"note":"Heat the nanocrystals in technical-grade TOPO following cited reference 32. The present paper does not restate the temperature, duration or amounts. The associated absorption/MCD specimen contains 1.1% Mn, but its initial feed is not supplied. Conditions from the amine treatment are not assigned to this procedure."},"norberg-2004-topo-op-2":{"title":"Frozen solution on quartz","art":"dropcoat","names":["TOPO-capped colloids"],"specimen":"Quartz disk","extra_rows":[{"label":"Specimen","value":"1.1% Mn"},{"label":"MCD temperature","value":"5 K"},{"label":"Solvent / deposited amount","value":"Not reported"}],"note":"Drop-coat the TOPO-capped 1.1% Mn colloids onto quartz disks to form frozen solutions for variable-field MCD at 5 K. Solvent identity, deposited amount and detailed TOPO preparation conditions are not supplied."},"norberg-2004-films-op-1":{"title":"Spin coating: films A–C","art":"spin","names":["Cleaned colloids"],"specimen":"Fused silica","extra_rows":[{"label":"Mn content","value":"0.20 ± 0.01%"},{"label":"Scope","value":"Films A–C only"}],"note":"Spin-coat the dodecylamine-treated 0.20 ± 0.01% Mn colloids onto 1 × 0.5 cm fused-silica substrates for films A–C. Spin speed, deposition time, dispensed volume and colloid concentration are not reported. Preparation details for films D–F remain separately incomplete."},"norberg-2004-films-op-2":{"title":"Per-layer annealing: films A–C","art":"anneal","names":[],"specimen":"Freshly coated substrate","extra_rows":[{"label":"Scope","value":"Each deposited layer, A–C"}],"note":"Anneal each deposited layer of films A–C in air at 525 °C for 2 min. Heating and cooling ramps are unreported. The cited 1 kbar solubility experiment does not establish an annealing pressure for these films."},"norberg-2004-films-op-3":{"title":"Repeat film deposition cycles","art":"cycles","names":[],"specimen":"Films A, B and C","extra_rows":[{"label":"Film A","value":"40 coats"},{"label":"Films B and C","value":"20 coats each"},{"label":"Films D–F","value":"Preparation details incomplete; A–C cycles not assigned"}],"note":"Repeat coating and the intervening annealing stages to obtain 40 coats for film A and 20 coats each for films B and C. The source does not independently specify coat counts, parent batches or annealing details for films D–F."},"norberg-2004-oxidation-controls-op-1":{"title":"Manganese precursor stability stock","art":"solution","names":["Mn(OAc)₂·4H₂O","DMSO"],"specimen":"Precursor solution","extra_rows":[{"label":"Context","value":"Separate from nanocrystal synthesis"}],"note":"Prepare the 0.002 M manganese(II) acetate tetrahydrate solution in DMSO. This precursor-stability experiment is separate from nanocrystal synthesis. The solution volume is not reported."},"norberg-2004-oxidation-controls-op-2":{"title":"Separate precursor control variants","art":"alternatives","names":[],"specimen":"Independent control solutions","extra_rows":[{"label":"Baseline","value":"Mn acetate in DMSO, air"},{"label":"Alternatives","value":"Zn acetate addition OR anaerobic handling"},{"label":"Acetate control","value":"0.010 M NaOAc, 5:1 to Mn"},{"label":"Nitrate control","value":"0.002 M Mn nitrate replaces Mn acetate"},{"label":"Gas / full Zn series","value":"Not reported"}],"note":"Compare the air-exposed manganese acetate baseline with separate zinc acetate, anaerobic, sodium acetate and manganese nitrate controls. The sodium acetate concentration is 0.010 M, a 5:1 ratio to Mn. The nitrate control uses 0.002 M manganese nitrate in place of manganese acetate. These alternatives are not combined in one solution. The anaerobic gas and full numerical zinc-ratio series are unspecified."},"norberg-2004-oxidation-controls-op-3":{"title":"Store and compare control solutions","art":"stability","names":[],"specimen":"Separate control solutions","extra_rows":[{"label":"Temperature","value":"Room temperature"},{"label":"Atmosphere","value":"Air-exposed variants open to air"},{"label":"Spectra","value":"Actual source data, no generated curve"}],"note":"Store the control solutions for five days and compare their absorption, including the probe at 20,000 cm⁻¹. The air-exposed variants remain open to the atmosphere; the discussion describes room-temperature oxidation. Control-specific outcomes remain separate, and no raw absorbance array or measured pH is supplied."},"norberg-2004-titration-op-1":{"title":"Titration starting mixture","art":"solution","names":["Mn / Zn acetates","DMSO"],"specimen":"One titration progression","extra_rows":[{"label":"Zn feed fraction","value":"98%"},{"label":"Absolute volumes","value":"Not reported"}],"note":"Prepare the Figure 1a titration mixture with 0.10 M total metal acetates in DMSO, comprising 2% Mn and 98% Zn. This series follows one base-addition progression; absolute volumes are unreported."},"norberg-2004-titration-op-2":{"title":"Incremental base titration","art":"titrate","names":["TMAH in ethanol"],"specimen":"Titration solution","extra_rows":[{"label":"Solid source trace","value":"1.65 equivalents"},{"label":"Clouding","value":"Beyond approximately 1.65 equivalents"},{"label":"Time between additions","value":"Not reported"}],"note":"Add 0.55 M ethanolic base successively in 0.15-equivalent increments. The solid Figure 1a trace corresponds to 1.65 equivalents. Further addition beyond approximately 1.65 equivalents causes clouding. The time between additions and the final excess increment are not reported."},"norberg-2004-titration-op-3":{"title":"Aliquot dilution and remeasurement","art":"dilute","names":[],"specimen":"Spectral aliquot","extra_rows":[{"label":"Temperature","value":"300 K"},{"label":"Optical path","value":"1 cm"},{"label":"Sequence","value":"Measure aliquot, dilute, remeasure"}],"note":"Withdraw an aliquot, measure its absorption, dilute it 70-fold and remeasure to capture weak and intense bands. The spectra are recorded at 300 K with a 1 cm optical path. Remeasurement of an aliquot does not create a separate synthesis."},"norberg-2004-early-aliquot":{"title":"Early growth aliquot","art":"aliquot","names":[],"specimen":"Early reaction bulk","extra_rows":[{"label":"Temperature","value":"Room temperature"},{"label":"Analysis specimen","value":"Washed and capped, in toluene"},{"label":"Lineage","value":"Remaining bulk continues separately"}],"note":"Withdraw the early aliquot after 10 min at room temperature. The spectra use washed and capped specimens dispersed in toluene; exact washing and capping quantities are unreported. The remaining reaction bulk continues separately from the analyzed aliquot."},"norberg-2004-continue-ripening":{"title":"Continue growth of remaining bulk","art":"heat","names":[],"specimen":"Remaining reaction bulk","extra_rows":[{"label":"Lineage","value":"Early analyzed aliquot is not returned"}],"note":"Continue growth of the original reaction bulk for 2 h at 60 °C before taking later aliquot c. The already analyzed early aliquot is not returned as the input to this stage."},"norberg-2004-later-aliquot":{"title":"Later growth aliquot","art":"aliquot","names":[],"specimen":"Later reaction bulk","extra_rows":[{"label":"Preparation","value":"Washed and capped for EPR"},{"label":"Lineage","value":"Separate aliquot; no reuse is asserted"}],"note":"Take the later aliquot after the stated growth period and prepare the washed, capped specimen for EPR. The source does not say that an already analyzed aliquot is reused in the subsequent cleaning stage."},"norberg-2004-clean-growth-product":{"title":"Clean later-growth product","art":"heat","names":["Dodecylamine"],"specimen":"Later-growth product","extra_rows":[{"label":"Handling","value":"Common N₂ cleaning, cooling and workup"},{"label":"Time qualifier","value":"Specimen-d passage states 30 min exactly"}],"note":"Wash the later-growth product and treat it at 180 °C for 30 min to obtain specimen d, as specified on printed page 9390. Nitrogen handling, cooling and workup are linked to the common amine procedure. This grouped description does not supply a separately complete SOP."},"norberg-2004-prepare-powder":{"title":"Prepare analytical powder","art":"precipitate","names":[],"specimen":"Toluene colloid","extra_rows":[{"label":"Method","value":"Rapid precipitation"},{"label":"Antisolvent / settings","value":"Not restated for this preparation"},{"label":"Aliquots","value":"XRD and magnetic powders not equated"}],"note":"Prepare powder by rapid precipitation from the toluene colloid for powder diffraction or magnetometry. The antisolvent and exact separation settings are not restated for this specimen preparation. The technique descriptions do not establish identical physical powder aliquots."},"norberg-2004-characterize-structure":{"title":"Structural characterization contexts","art":"structure","names":[],"specimen":"Separate source specimens","extra_rows":[{"label":"Methods","value":"TEM / HRTEM; powder and thin-film XRD"},{"label":"Assignments","value":"Figure 3 panel-specific specimens"},{"label":"Atomic coordinates","value":"No refined sample coordinates or CIF supplied"}],"note":"Characterize the source-defined specimens by TEM/HRTEM, powder XRD and thin-film XRD, preserving the separate Figure 3 panel assignments. The paper supplies no SAED, refined lattice constants, atomic coordinates or CIF."},"norberg-2004-acquire-optics":{"title":"Compare optical specimens","art":"optical-compare","names":[],"specimen":"Separate capped colloids","extra_rows":[{"label":"Specimens","value":"Undoped; 0.13% Mn estimated; 1.3% Mn reported"},{"label":"Normalization","value":"Absorption at excitation; emission scaled proportionally"}],"note":"Compare separate undoped, estimated 0.13% Mn and reported 1.3% Mn dodecylamine-capped colloids. Normalize absorption at the excitation energy and scale emission proportionally. No common exact feed or physical batch is inferred from the shared measurement conditions."},"norberg-2004-acquire-magnetism":{"title":"SQUID specimen comparison","art":"magnetic-compare","names":[],"specimen":"Powder and films A–C","extra_rows":[{"label":"Contexts","value":"Separate source specimens"},{"label":"Scope","value":"Keep temperatures, fields and model comparisons attached"}],"note":"Measure the colloid powder and films A–C separately by SQUID magnetometry. Keep each temperature, field and model comparison attached to its reported specimen context."},"norberg-2004-zfc-series":{"title":"Zero-field-cooled magnetometry","art":"magnetic","names":[],"specimen":"Films A and B","extra_rows":[{"label":"Temperature interval","value":"5–350 K"},{"label":"Observed result","value":"No transition over measured interval"}],"note":"Measure the zero-field-cooled series for films A and B at 80 Oe. No transition is observed over 5–350 K. This observation does not provide a universal impurity-detection limit."},"norberg-2004-film-epr":{"title":"Film and precursor EPR comparison","art":"epr-compare","names":[],"specimen":"Film A / precursor colloid","extra_rows":[{"label":"Additional signal","value":"g = 2.00"},{"label":"Interpretation","value":"Tentative radical / redox assignment"},{"label":"Unmeasured","value":"N content and carrier polarity"}],"note":"Compare the separate EPR spectra of film A and its precursor colloid. The new sharp g = 2.00 resonance has a tentative radical/redox interpretation; carrier polarity and nitrogen content were not measured."},"norberg-2004-acquire-epr-x":{"title":"X-band EPR acquisition","art":"epr","names":[],"specimen":"Colloid or film specimen","extra_rows":[{"label":"Instrument","value":"Bruker EMX"},{"label":"Temperature","value":"Room temperature; figure-specific 300 K"},{"label":"Film mounting","value":"Nonmagnetic tape; film perpendicular to field"}],"note":"Acquire X-band EPR with a Bruker EMX at 9.34 GHz and room temperature; the figure-specific spectra state 300 K. Colloids are dispersed in toluene. For the film measurement, the film is attached to the EPR tube with nonmagnetic tape and oriented perpendicular to the field. Shared settings do not imply a shared specimen."},"norberg-2004-acquire-epr-q":{"title":"Q-band EPR acquisition","art":"epr","names":[],"specimen":"Toluene colloid","extra_rows":[{"label":"Instrument","value":"Bruker ESP300E"},{"label":"Temperature","value":"Room temperature"}],"note":"Acquire Q-band EPR of toluene-dispersed colloids using a Bruker ESP300E at 34.0 GHz and room temperature. Keep the experimental spectra separate from fitted or simulated traces."},"norberg-2004-acquire-epr-sim":{"title":"EPR model calculation","art":"model","names":[],"specimen":"Model parameters","extra_rows":[{"label":"Software","value":"Høgni Weihe SIM, version 2002"},{"label":"Method","value":"Full-matrix diagonalization"},{"label":"Hamiltonian","value":"Equation 1"},{"label":"Status","value":"Calculated traces, not measured atomic coordinates"}],"note":"Simulate EPR spectra with Høgni Weihe's SIM version 2002 using full-matrix diagonalization and the Hamiltonian in Equation 1. These traces are model calculations, not additional measured spectra or refined atomic coordinates."},"norberg-2004-acquire-abs":{"title":"Electronic absorption acquisition","art":"optical","names":[],"specimen":"Colloid or film A context","extra_rows":[{"label":"Instrument","value":"Cary 500E Varian"},{"label":"Temperature","value":"Room temperature"},{"label":"Aliquot dilution","value":"70-fold only in the separate titration procedure"}],"note":"Record electronic absorption with a Cary 500E Varian spectrometer using a 1 cm optical path at room temperature. Colloid and film A spectra retain their separate specimen assignments. The 70-fold redilution applies specifically to the titration aliquot procedure."},"norberg-2004-acquire-mcd":{"title":"Magnetic circular dichroism","art":"mcd","names":[],"specimen":"Frozen TOPO-capped colloids","extra_rows":[{"label":"Specimen","value":"1.1% Mn on quartz"},{"label":"Apparatus","value":"Referred to prior work"}],"note":"Measure MCD of the frozen, drop-coated TOPO-capped 1.1% Mn colloids on quartz at 5 K over 0–7 T. The apparatus is referenced to prior work rather than restated. Preserve the printed normalization and distinguish measured field dependence from the Brillouin comparison."},"norberg-2004-acquire-lum":{"title":"Luminescence acquisition","art":"lum","names":[],"specimen":"Source-defined optical specimen","extra_rows":[{"label":"Instrument","value":"Jobin Yvon FluoroMax-2"}],"note":"Acquire luminescence with a Jobin Yvon FluoroMax-2 using a 1 × 1 cm cuvette, excitation at 28,200 cm⁻¹ and a temperature of 300 K. The distinct optical specimens and their normalization remain source-scoped."},"norberg-2004-acquire-xrd-powder":{"title":"Powder diffraction acquisition","art":"xrd-powder","names":[],"specimen":"Powder specimen","extra_rows":[{"label":"Instrument","value":"Philips PW1830"},{"label":"Radiation","value":"Cu Kα"}],"note":"Acquire powder diffraction using a Philips PW1830 with Cu Kα radiation. Keep the powder specimen distinct from the separately measured thin film."},"norberg-2004-acquire-xrd-film":{"title":"Thin-film diffraction acquisition","art":"xrd-film","names":[],"specimen":"Thin-film specimen","extra_rows":[{"label":"Instrument","value":"Rigaku Rotaflex RTP300"},{"label":"Radiation","value":"Cu Kα"}],"note":"Acquire thin-film diffraction using a Rigaku Rotaflex RTP300 with Cu Kα radiation. The instrument description does not identify the film as the same physical specimen used by every other technique."},"norberg-2004-acquire-tem":{"title":"High-resolution electron microscopy","art":"tem","names":[],"specimen":"Microscopy specimen","extra_rows":[{"label":"Instrument","value":"JEOL 2010"},{"label":"Electron source","value":"High-brightness LaB₆"}],"note":"Acquire HRTEM using a JEOL 2010 at 200 kV with a high-brightness LaB₆ electron source. Imaging voltage is an acquisition condition, not a nanocrystal synthesis temperature or energy."},"norberg-2004-acquire-icp":{"title":"Elemental analysis by ICP-AES","art":"icp","names":[],"specimen":"Analytical aliquot","extra_rows":[{"label":"Instrument","value":"Jarrel Ash 955"},{"label":"Reported purpose","value":"Dopant concentration"}],"note":"Determine dopant concentration by ICP-AES using the source-described Jarrel Ash 955 instrument. Preserve the identified analytical specimen and reported concentration uncertainty."},"norberg-2004-acquire-mag":{"title":"SQUID magnetometry acquisition","art":"magnetic","names":[],"specimen":"Powder or thin film","extra_rows":[{"label":"Instrument","value":"Quantum Design MPMS-5S"},{"label":"Correction","value":"Subtract substrate and holder diamagnetism"},{"label":"Ceiling meaning","value":"Limits the reported Curie-temperature bound"}],"note":"Use a Quantum Design MPMS-5S SQUID magnetometer for rapidly precipitated colloid powders or spin-coated films, subtracting substrate and holder diamagnetism. The instrument temperature ceiling is 350 K; it limits the reported Curie-temperature bound. Measurements and model-derived magnetic quantities remain distinct."}},"parameter_labels":{"frequency_GHz":"Microwave frequency","path_length_cm":"Optical path","temperature_K":"Temperature","field_T_range":"Magnetic field","cuvette_dimension_1":"Cuvette dimension 1","cuvette_dimension_2":"Cuvette dimension 2","excitation_cm-1":"Excitation wavenumber","accelerating_voltage_kV":"Accelerating voltage","instrument_temperature_ceiling_K":"Instrument temperature ceiling","temperature":"Temperature","duration":"Duration","precipitation_temperature_limit":"Temperature before precipitation","substrate_length":"Substrate length","substrate_width":"Substrate width","spin_speed":"Spin speed","spin_duration":"Spin duration","dispensed_volume":"Dispensed volume","per_layer_duration":"Duration per layer","time_after_base_addition":"Time after base addition","combined_metal_concentration":"Total metal concentration","reaction_volume":"Reaction volume","base_equivalents":"Base amount · mixture basis","base_stock_concentration":"Base stock concentration","stirring_speed":"Stirring speed","addition_duration":"Addition duration","initial_capping_temperature":"Initial capping temperature","initial_capping_duration":"Initial capping duration","dodecylamine_charge":"Dodecylamine charge","measurement_field":"Measurement field","excitation_absorbance_range":"Absorbance at excitation","excitation_wavenumber":"Excitation wavenumber","Mn_concentration":"Manganese concentration","absorption_probe":"Absorption probe","storage_duration":"Storage duration","Mn_relative_to_Zn":"Added Mn relative to Zn","LiOH_charge_basis_unspecified":"LiOH amount · equivalent basis unknown","Mn_feed_fraction":"Mn feed fraction","base_increment":"Base increment","remeasurement_dilution":"Remeasurement dilution","TOPO_charge":"TOPO charge"},"records":{"norberg-2004-acquisition-methods":["norberg-2004-acquire-epr-x","norberg-2004-acquire-epr-q","norberg-2004-acquire-epr-sim","norberg-2004-acquire-abs","norberg-2004-acquire-mcd","norberg-2004-acquire-lum","norberg-2004-acquire-xrd-powder","norberg-2004-acquire-xrd-film","norberg-2004-acquire-tem","norberg-2004-acquire-icp","norberg-2004-acquire-mag"],"norberg-2004-amine-cleaning":["norberg-2004-amine-cleaning-op-1","norberg-2004-amine-cleaning-op-2","norberg-2004-amine-cleaning-op-3","norberg-2004-amine-cleaning-op-4"],"norberg-2004-films-a-c":["norberg-2004-films-op-1","norberg-2004-films-op-2","norberg-2004-films-op-3"],"norberg-2004-growth-series":["norberg-2004-early-aliquot","norberg-2004-continue-ripening","norberg-2004-later-aliquot","norberg-2004-clean-growth-product"],"norberg-2004-hydrolysis":["norberg-2004-hydrolysis-op-1","norberg-2004-hydrolysis-op-2","norberg-2004-hydrolysis-op-3","norberg-2004-hydrolysis-op-4","norberg-2004-hydrolysis-op-5","norberg-2004-hydrolysis-op-6","norberg-2004-hydrolysis-op-7"],"norberg-2004-magnetism":["norberg-2004-acquire-magnetism","norberg-2004-zfc-series","norberg-2004-film-epr"],"norberg-2004-optical":["norberg-2004-acquire-optics"],"norberg-2004-oxidation-controls":["norberg-2004-oxidation-controls-op-1","norberg-2004-oxidation-controls-op-2","norberg-2004-oxidation-controls-op-3"],"norberg-2004-structure":["norberg-2004-prepare-powder","norberg-2004-characterize-structure"],"norberg-2004-surface-control":["norberg-2004-surface-control-op-1","norberg-2004-surface-control-op-2","norberg-2004-surface-control-op-3","norberg-2004-surface-control-op-4"],"norberg-2004-titration":["norberg-2004-titration-op-1","norberg-2004-titration-op-2","norberg-2004-titration-op-3"],"norberg-2004-topo":["norberg-2004-topo-op-1","norberg-2004-topo-op-2"]}};
// Norberg 2004: source-specific explanatory apparatus. No measured geometry.
const C={ink:'#173c4b',muted:'#557381',line:'#7b9baa',pale:'#f1f7fa',blue:'#dcecf3',gold:'#d5a34a',particle:'#607e9a',green:'#217862'};
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const text=(x,y,s,size=16,anchor='middle',fill=C.ink,weight=400)=>`<text x="${x}" y="${y}" text-anchor="${anchor}" font-family="Arial,sans-serif" font-size="${size}" font-weight="${weight}" fill="${fill}">${esc(s)}</text>`;
const path=(d,color=C.line,w=2.4,extra='')=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" ${extra}/>`;
const rect=(x,y,w,h,fill=C.pale,rx=10)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}" stroke="${C.line}" stroke-width="1.5"/>`;
const arrow=(x,y,a=0,color=C.line)=>`<g transform="translate(${x} ${y}) rotate(${a})">${path('M-20 0H20M12 -7L20 0L12 7',color,2.8)}</g>`;
function wrap(s,max=58){const lines=[];let row='';for(const word of String(s).split(/\s+/)){if(row&&(`${row} ${word}`).length>max){lines.push(row);row=word;}else row+=(row?' ':'')+word;}if(row)lines.push(row);return lines;}
const para=(x,y,s,{max=45,size=14,line=19,anchor='start',fill=C.muted}={})=>wrap(s,max).map((t,i)=>text(x,y+i*line,t,size,anchor,fill)).join('');
function quantity(q){if(q.value!=null)return `${q.approximate?'≈ ':''}${q.value} ${q.unit==='degC'?'°C':q.unit??''}`.trim();if(q.minimum!=null&&q.maximum!=null)return `${q.minimum}–${q.maximum} ${q.unit}`;if(q.maximum!=null)return `${q.maximum_exclusive?'<':'≤'} ${q.maximum} ${q.unit}`;if(q.minimum!=null)return `${q.minimum_exclusive?'>':'≥'} ${q.minimum} ${q.unit}`;return 'Not reported';}
function particles(x,y,pellet=false){return [[-27,7],[16,-7],[31,27],[-6,31],[-33,32]].map(([a,b],i)=>`<circle cx="${x+a}" cy="${pellet?y+38+(i%2)*4:y+b}" r="6" fill="${C.particle}"/>`).join('');}
function vessel(x,y,{dots=false,pellet=false,heat=false,label='',cap=false}={}){
 let s=`<path d="M${x-53} ${y-62}V${y+55}Q${x-53} ${y+72} ${x-37} ${y+72}H${x+37}Q${x+53} ${y+72} ${x+53} ${y+55}V${y-62}" fill="#fff" stroke="${C.line}" stroke-width="2.5"/><path d="M${x-49} ${y-5}H${x+49}V${y+53}Q${x+49} ${y+67} ${x+35} ${y+67}H${x-35}Q${x-49} ${y+67} ${x-49} ${y+53}Z" fill="${C.blue}"/>`;
 if(dots||pellet)s+=particles(x,y+3,pellet);
 if(cap)s+=rect(x-54,y-74,108,14,'#adbec6',3);
 if(heat)s+=rect(x-70,y+89,140,17,'#efe0c5',3)+[-36,0,36].map(a=>path(`M${x+a} ${y+86}q-5 -7 0 -14q5 -7 0 -14`,C.gold,2)).join('');
 return s+para(x,y+(heat?132:101),label,{max:35,size:13,line:17,anchor:'middle'});
}
function bottle(x,y,label){return rect(x-26,y-33,52,65,'#edf4f7',6)+rect(x-19,y-45,38,14,'#a9bfc9',3)+para(x,y+54,label,{max:19,size:13,line:16,anchor:'middle',fill:C.ink});}
function charge(c,dots=false,drop=false){let s=vessel(190,300,{dots,label:c.specimen});
 const names=c.names.length?c.names:['Source-defined input'];
 s+=names.map((n,i)=>bottle(names.length===1?116:85+i*155,158,n)).join('');
 if(drop){s+=path('M119 207v35',C.line,3)+[254,264,274].map(y=>`<circle cx="119" cy="${y}" r="2" fill="${C.line}"/>`).join('');if(c.art==='drop')s+=path('M164 335q24 -18 48 0',C.line,2)+arrow(209,331,20);}
 else s+=arrow(137,235,43);
 return s;
}
function precipitation(c){return vessel(97,252,{dots:true,label:c.specimen})+arrow(190,263)+vessel(289,252,{pellet:true,label:'Retain particle fraction'})+para(192,141,c.names.length?c.names.join(' + '):'Rapid precipitation; antisolvent unspecified',{max:36,size:16,line:21,anchor:'middle',fill:C.ink})+text(193,409,'Separation equipment is not specified',13,'middle',C.muted);}
function redisperse(c){return vessel(96,256,{pellet:true,label:'Recovered particles'})+arrow(190,258)+vessel(290,256,{dots:true,label:c.names.join(' / ')})+text(190,156,'Redispersion',20,'middle',C.ink,600);}
function wash(c){return vessel(98,260,{pellet:true,label:'Retain particle fraction'})+arrow(188,229)+arrow(188,302,180)+vessel(286,260,{dots:true,label:'Resuspended colloids'})+para(190,141,c.names.join(' / '),{max:38,size:17,line:22,anchor:'middle',fill:C.ink})+text(190,411,'Wash / recovery settings remain unspecified',13,'middle',C.muted);}
function thermal(c,cool=false){return vessel(190,258,{dots:true,heat:!cool,label:c.specimen})+(cool?arrow(93,196,90,'#4b8fba')+arrow(285,196,90,'#4b8fba')+text(190,145,'Cooling',20,'middle',C.ink,600):para(190,145,c.names.length?c.names.join(' + '):'Thermal growth / treatment',{max:36,size:17,line:22,anchor:'middle',fill:C.ink}))+text(190,439,cool?'Cooling method not reported':'Heating support is generic',13,'middle',C.muted);}
function aliquot(c){return vessel(111,267,{dots:true,label:c.specimen})+path('M231 170l-59 92',C.line,7)+arrow(252,248,28)+rect(291,264,36,80,C.blue,3)+text(308,377,'Aliquot',14)+text(191,150,'Sample the reaction bulk',19,'middle',C.ink,600)+text(191,423,'Remaining bulk and sampled aliquot are distinct',13,'middle',C.muted);}
function substrate(x,y,label){return `<path d="M${x-66} ${y}l80 -22l53 24l-80 23Z" fill="#d9e9f1" stroke="${C.line}" stroke-width="2"/>`+text(x,y+62,label,14);}
function film(c,kind){
 if(kind==='cycles')return [90,197,304].map((x,i)=>`<g transform="translate(${x} 240) scale(.7)">${substrate(0,0,'')}</g>`+text(x,305,['Film A','Film B','Film C'][i],14)+text(x,343,i===0?'40 coats':'20 coats',17,'middle',C.green,600)).join('')+text(193,153,'Coat → anneal → repeat',20,'middle',C.ink,600)+text(193,414,'Preparation scope: A–C only',15,'middle',C.muted);
 if(kind==='anneal')return rect(64,151,257,223,'#efe8dd',12)+rect(88,179,209,160,'#fff',6)+substrate(187,261,'Deposited layer')+[-35,0,35].map(a=>path(`M${189+a} 229q-7 -10 0 -20q7 -10 0 -20`,C.gold,2)).join('')+text(192,416,'Generic thermal chamber · air',14,'middle',C.muted);
 let s=kind==='spin'?substrate(190,283,'')+text(190,377,'Fused-silica substrate',14):`<ellipse cx="190" cy="296" rx="76" ry="26" fill="#d9e9f1" stroke="${C.line}" stroke-width="2"/>`+text(190,358,'Quartz disk',14);
 s+=path('M209 172l-24 77',C.line,6)+`<circle cx="184" cy="259" r="4" fill="${C.particle}"/>`+para(193,137,c.names.join(' / '),{max:34,size:16,line:21,anchor:'middle',fill:C.ink});
 if(kind==='spin')s+=`<ellipse cx="190" cy="331" rx="99" ry="16" fill="none" stroke="${C.line}" stroke-width="2"/>`+arrow(267,321,-10)+text(191,414,'Spin coating · speed not reported',14,'middle',C.muted);
 else s+=text(192,421,'Frozen solution for MCD',16,'middle',C.muted);
 return s;
}
function alternatives(){const open=(x,y,label)=>path(`M${x-25} ${y-33}v65h50v-65`,C.line,2)+rect(x-23,y,46,29,C.blue,1)+text(x,y+55,label,13);return [85,195,305].map((x,i)=>i===2?bottle(x,235,'Anaerobic'):open(x,235,['Air baseline','Zn acetate'][i])).join('')+[125,270].map((x,i)=>open(x,359,['NaOAc control','Mn nitrate control'][i])).join('')+text(191,146,'Independent solution variants',19,'middle',C.ink,600);}
function optical(c,lum=false){let s=rect(48,240,65,57,'#d4e3eb')+arrow(136,269)+rect(178,210,46,119,C.blue,4)+arrow(250,269)+rect(290,240,58,57,'#d4e3eb');if(lum)s+=arrow(201,179,-90,'#9180bc')+rect(174,131,57,24,'#e2dcec',5);return s+para(197,378,c.specimen,{max:41,size:16,line:21,anchor:'middle',fill:C.ink})+text(197,431,'Generic acquisition geometry; source curves separate',13,'middle',C.muted);}
function magnet(c,epr=false){return path('M97 193v131q0 31 34 31h121q31 0 31 -31V193','#9ab2bf',30)+rect(174,224,37,76,'#d4e3eb',4)+arrow(150,256)+arrow(242,256)+text(192,159,epr?'Microwave field / specimen':'Magnetic field / specimen',18,'middle',C.ink,600)+para(192,403,c.specimen,{max:39,size:15,line:21,anchor:'middle'});}
function comparison(c,kind){const labels=kind==='optical-compare'?['Undoped','0.13% Mn','1.3% Mn']:kind==='magnetic-compare'?['Powder','Film A','Film B','Film C']:['Film A','Precursor colloid'];const w=labels.length===4?76:labels.length===3?103:139;return labels.map((label,i)=>{const x=192+(i-(labels.length-1)/2)*(w+10);return rect(x-w/2,228,w,104,i%2?'#dce5eb':'#e5edf4',6)+para(x,276,label,{max:17,size:14,line:20,anchor:'middle',fill:C.ink});}).join('')+para(192,158,c.specimen,{max:34,size:18,line:23,anchor:'middle',fill:C.ink})+text(192,380,'Separate source specimens',16,'middle',C.ink,600)+text(192,420,kind==='epr-compare'?'Film A compared with precursor colloid':'No physical mixing or shared batch inferred',13,'middle',C.muted);}
function diffraction(c,filmMode=false){return rect(56,178,63,45,'#d5e5ed',6)+path('M115 224L194 289L290 199','#b09257',3)+substrate(191,302,filmMode?'Thin-film specimen':'Powder specimen')+(filmMode?'':`<g transform="translate(191 275) scale(.65)">${particles(0,0,true)}</g>`)+rect(284,175,41,75,'#d5e5ed',4)+text(192,148,'X-ray diffraction',20,'middle',C.ink,600)+text(192,422,'No artificial diffraction peaks or pattern',13,'middle',C.muted);}
function electron(c){return rect(75,144,86,212,'#deebf1',10)+arrow(118,204,90)+rect(89,292,57,11,'#aabfc8',3)+arrow(209,271)+rect(271,223,60,72,'#edf4f8',4)+text(118,395,'Electron probe',15)+text(299,333,'Source image',14)+text(191,445,'No invented lattice image or diffraction pattern',13,'middle',C.muted);}
function model(){return rect(50,178,291,177,'#e6eef4',10)+rect(70,199,251,114,'#fff',4)+text(194,240,'Spin Hamiltonian · Equation 1',17)+text(194,280,'Full-matrix diagonalization',16)+path('M172 357v27h-40m40 0h58',C.line,3)+text(193,431,'Calculated EPR traces; not measured atom positions',13,'middle',C.muted);}
function sceneArt(c){switch(c.art){
 case 'charge':case 'solution':return charge(c,false);
 case 'drop':case 'titrate':return charge(c,false,true);
 case 'particle-drop':return charge(c,true,true);
 case 'particle-add':case 'cap':return charge(c,true);
 case 'precipitate':return precipitation(c);case 'redisperse':return redisperse(c);case 'wash':return wash(c);
 case 'heat':return thermal(c);case 'cool':return thermal(c,true);
 case 'ripen':return vessel(190,279,{dots:true,label:c.specimen})+text(190,151,'Initial growth → further ripening',18,'middle',C.ink,600)+text(190,426,'Room-temperature / near-60 °C alternatives',13,'middle',C.muted);
 case 'control-particles':return vessel(191,271,{dots:true,label:'Pure ZnO in ethanol'})+text(191,155,'No manganese in upstream feed',18,'middle',C.ink,600);
 case 'spin':case 'anneal':case 'cycles':case 'dropcoat':return film(c,c.art);
 case 'aliquot':return aliquot(c);case 'alternatives':return alternatives();
 case 'stability':return alternatives()+text(191,468,'Store, then compare absorption',15,'middle',C.muted);
 case 'dilute':return rect(71,224,43,113,C.blue,4)+arrow(157,279)+rect(196,224,43,113,'#ecf4f8',4)+arrow(282,279)+rect(321,240,35,70,C.pale,4)+text(94,371,'Aliquot',15)+text(219,371,'Diluted',15)+text(337,371,'Read',15)+text(195,165,'Measure → dilute → remeasure',18,'middle',C.ink,600);
 case 'optical':case 'lum':return optical(c,c.art==='lum');
 case 'magnetic':case 'epr':case 'mcd':return magnet(c,c.art==='epr');
 case 'optical-compare':case 'magnetic-compare':case 'epr-compare':return comparison(c,c.art);
 case 'xrd-powder':case 'xrd-film':return diffraction(c,c.art==='xrd-film');case 'tem':return electron(c);
 case 'model':return model();
 case 'structure':return rect(65,166,255,67,C.pale,9)+text(192,206,'TEM / HRTEM',20)+rect(65,261,255,67,C.pale,9)+text(192,301,'Powder / thin-film XRD',19)+text(192,398,'Keep panel and specimen assignments',14,'middle',C.muted);
 case 'icp':return bottle(84,273,'Analytical aliquot')+arrow(146,273)+path('M190 332q-29 -73 0 -109q27 33 0 109',C.gold,9)+arrow(239,273)+rect(281,230,60,87,C.pale,5)+text(190,155,'ICP-AES analysis',20,'middle',C.ink,600)+text(193,407,'Elemental concentration; no atom map',14,'middle',C.muted);
 default:throw Error('Unknown scene art '+c.art);
}}
export function buildNorberg2004Scene(o,r){
 if(r?.lineage?.source_group!=='norberg2004'||!DATA.records[r.record_id]?.includes(o?.id))return null;
 const c=DATA.configs[o.id];if(!c)return null;
 const rows=Object.entries(o.parameters??{}).map(([k,q])=>({label:DATA.parameter_labels[k],value:quantity(q)})).concat(c.extra_rows);
 if(o.environment?.value)rows.push({label:'Atmosphere',value:o.environment.value});
 if(o.stage!=='characterization'&&!rows.some(x=>/pressure/i.test(x.label)))rows.push({label:'Numerical pressure',value:'Not reported'});
 let y=130,panel='';for(const row of rows){const lines=wrap(row.value,49);panel+=text(422,y,row.label,12,'start',C.muted,600)+lines.map((line,i)=>text(422,y+23+i*20,line,16,'start',C.ink,500)).join('');y+=Math.max(1,lines.length)*20+35;}
 const divider=Math.max(510,y+5),notes=wrap(c.note,115),height=divider+78+notes.length*19;
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 ${height}" role="img" aria-label="${esc(c.title)}" style="width:100%;height:auto"><title>${esc(c.title)}</title><desc>Norberg et al. 2004. Source-specific inputs and conditions; geometry, colors and particles are illustrative, not measured apparatus or atomic coordinates.</desc><rect width="900" height="${height}" rx="18" fill="#fff"/>${text(28,38,c.title,24,'start',C.ink,600)}${text(28,72,o.stage==='characterization'?'ACQUISITION / MODEL CONTEXT':'SOURCE PREPARATION / MATERIAL FLOW',12,'start',C.muted,600)}${sceneArt(c)}${rect(398,96,476,divider-114,'#f3f8fb',14)}${panel}${path(`M28 ${divider}H872`,'#d9e6ec',1)}${notes.map((line,i)=>text(29,divider+30+i*19,line,14,'start',C.muted)).join('')}${text(28,height-19,'Illustrative geometry and particle symbols · no measured atomic coordinates or surface coverage',11,'start',C.muted)}</svg>`;
 return {kind:`${r.record_id}--${o.id}`,svg,caption:'Source-specific explanatory schematic. Labels retain the reported inputs, conditions, sample scopes and missingness. Geometry, colors and particle symbols are illustrative.'};
}
export function createNorberg2004Art(o,r){const s=buildNorberg2004Scene(o,r);if(!s)return null;const d=document.createElement('div');d.className='protocol-art protocol-art-norberg2004';d.dataset.scene='norberg2004-'+s.kind;d.style.height='auto';d.innerHTML=s.svg;return d;}
export const norberg2004SceneSelection={source_group:'norberg2004',records:DATA.records};
